import json, os, re, urllib.request, urllib.error
raw = os.environ["BLAND_API_KEY"].strip()
if raw.startswith("{"):
    p = json.loads(raw); raw = next((p[k] for k in ("api_key", "key", "value") if p.get(k)), raw)
PW = "94abad8b-fbe2-4e67-9c64-d9b586dd2653"
mask = lambda s: re.sub(r"\d{7,}", lambda m: "***" + m.group(0)[-4:], str(s))

def call(path):
    req = urllib.request.Request("https://api.bland.ai" + path, headers={"Authorization": raw, "Content-Type": "application/json", "User-Agent": "mybcat-cli"})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            return r.status, json.loads(r.read().decode() or "{}")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode(errors="replace")[:200]

print("=== PATHWAY VERSIONS ===")
st, body = call("/v1/pathway/%s/versions" % PW)
rows = body if isinstance(body, list) else ((body.get("data") or body.get("versions") or []) if isinstance(body, dict) else [])
nums = []
for v in rows:
    if isinstance(v, dict):
        n = v.get("version_number", v.get("version"))
        if isinstance(n, int):
            nums.append(n)
nums.sort()
for v in rows[-8:] if isinstance(rows, list) else []:
    if isinstance(v, dict):
        print("  v%s created=%s name=%s" % (v.get("version_number", v.get("version")), str(v.get("created_at", ""))[:19], str(v.get("name", ""))[:60]))
latest = nums[-1] if nums else "NONE"
print("LATEST_VERSION=%s (list HTTP %s, %d versions)" % (latest, st, len(nums)))

def welcome_texts(ver):
    s, b = call("/v1/pathway/%s/version/%s" % (PW, ver))
    found = []
    def walk(o, path=""):
        if isinstance(o, dict):
            for k, val in o.items():
                walk(val, path + "/" + str(k))
        elif isinstance(o, list):
            for i, val in enumerate(o):
                walk(val, path)
        elif isinstance(o, str) and "MK2 Optical" in o and ("visit" in o or "exam" in o or "Hi " in o or "reply" in o.lower()):
            found.append((path[:80], o))
    walk(b)
    print("--- v%s welcome-bearing texts (HTTP %s, %d found) ---" % (ver, s, len(found)))
    seen = set()
    for pth, t in found:
        if t in seen:
            continue
        seen.add(t)
        print("  at %s:" % pth)
        print("  " + mask(t)[:700].replace("\n", "\n  "))
    if not found:
        print("  NO_WELCOME_FOUND")

welcome_texts(123)
if latest != "NONE" and latest != 123:
    welcome_texts(latest)
else:
    print("--- no newer version than 123 exists ---")
print("VERSIONS_DONE")
